xccdf-1.2:Rule.xccdf-1.2:fix:
include install_firewalld

class install_firewalld {
  package { 'firewalld':
    ensure => 'installed',
  }
}

include enable_firewalld

class enable_firewalld {
  service {'firewalld':
    enable => true,
    ensure => 'running',
  }
}

include remove_dnsmasq

class remove_dnsmasq {
  package { 'dnsmasq':
    ensure => 'purged',
  }
}

include disable_dnsmasq

class disable_dnsmasq {
  service {'dnsmasq':
    enable => false,
    ensure => 'stopped',
  }
}

include remove_bind

class remove_bind {
  package { 'bind':
    ensure => 'purged',
  }
}

include remove_bind9.18

class remove_bind9.18 {
  package { 'bind9.18':
    ensure => 'purged',
  }
}

include disable_named

class disable_named {
  service {'named':
    enable => false,
    ensure => 'stopped',
  }
}
